/// <summary>UNIQUE constraints of the customers table as data, walked by the shared engine (<see cref="UniquenessChecker"/>).</summary>
/// <remarks>
/// The checks are dialect-neutral (they build the same expression trees the per-target inline code used to),
/// which is why the table lives beside the contract and is shared by every implementation target.
/// </remarks>
internal static class CustomerUniquenessConstraints
{
    /// <summary>The constraint checks, in declaration order.</summary>
    public static readonly IReadOnlyList<UniquenessConstraintCheck<CustomerEntity>> Checks =
        new UniquenessConstraintCheck<CustomerEntity>[]
        {
            new(
                "UQ_customers_name",
                new[]
                {
                    nameof(CustomerEntity.Name),
                },
                static entity => entity.Name is not null,
                static (query, entity) =>
                    query
                        .Where(candidate => candidate.Name == entity.Name)
            ),
            new(
                "UQ_customers_code",
                new[]
                {
                    nameof(CustomerEntity.Code),
                },
                static entity => entity.Code is not null,
                static (query, entity) =>
                    query
                        .Where(candidate => candidate.Code == entity.Code)
            ),
        };

    /// <summary>Excludes the entity's own row from a candidate query.</summary>
    public static SqlQuery<CustomerEntity> ExcludeSelf(SqlQuery<CustomerEntity> query, CustomerEntity entity) =>
        query.Where(candidate => candidate.CustomerId != entity.CustomerId);

    /// <summary>The constraint table and the self-exclusion as one value (what each repository hands to its base class).</summary>
    public static readonly UniquenessConstraintSet<CustomerEntity> Set =
        new(Checks, ExcludeSelf);
}

